import {SUPPLIES,shiftScore} from './vitals.js';
const n=v=>Number(v.toFixed(1));
export function scoreBreakdown(s,points,max){const r=shiftScore(s,points,max);return`<div class="shift-score"><strong>${n(r.total)}<small> / 100</small></strong><span>任務 ${n(r.task)} / 70 ＋ 交班狀態 ${n(r.condition)} / 30</span></div><div class="condition-score"><span>體力 <b>${Math.round(s.energy)}</b><small>${n(r.energy)} / 10</small></span><span>飽足 <b>${Math.round(s.hunger)}</b><small>${n(r.hunger)} / 10</small></span><span>脾氣 <b>${Math.round(s.temper)}</b><small>${n(r.temper)} / 10 · 越低越好</small></span></div>`;}
export function vitalRulesHTML({explore=false}={}){return`<h2 id="modalTitle">照顧病人，也照顧自己。</h2><p class="modal-copy">總分 100：任務占 70 分；交班時體力、飽足及脾氣各占 10 分。脾氣越低，分數越高。</p><div class="vital-rules"><table><thead><tr><th>情境</th><th>體力</th><th>飽足</th><th>脾氣</th></tr></thead><tbody><tr><td>完成一件工作</td><td>−6</td><td>−5</td><td>−4</td></tr><tr><td>一般／緊急來電</td><td>—</td><td>—</td><td>+8／+12</td></tr><tr><td>選錯一次</td><td>—</td><td>—</td><td>+8</td></tr><tr><td>跨棟／搭電梯</td><td>−1</td><td>—</td><td>+1</td></tr><tr><td>坐下，每秒</td><td>+1.5</td><td>−0.04</td><td>−0.4</td></tr><tr><td>躺下，每秒</td><td>+3</td><td>−0.04</td><td>−0.8</td></tr>${Object.values(SUPPLIES).map(f=>`<tr><td>${f.name} · ${f.minutes} 分鐘</td><td>+${f.energy}</td><td>+${f.hunger}</td><td>${f.temper}</td></tr>`).join('')}</tbody></table></div><p class="modal-copy">走動每秒耗 0.12 體力，站著耗 0.03；飽足每秒 −0.04。閱讀題目與暫停時停止消耗，坐著接電話仍會恢復體力。彩蛋成功可緩和 5～6 脾氣，每個地點一次；刀房操作請學長接手可緩和5。</p><div class="vital-thresholds"><p><b>體力 ≤10</b>先坐下或躺下，恢復到 30 才能站起來工作。</p><p><b>飽足 =0</b>先吃東西，恢復到 25 才能繼續；身邊有備用餅乾可應急。</p><p><b>脾氣 =100</b>爆炸 3 秒！冷靜後回到 65，體力 −8，遊戲時間 +3 分鐘，工作進度保留。</p></div>${explore?'<details class="care-demos"><summary>自由探索 · 體驗數值事件</summary><div class="inline-actions"><button data-care-demo="energy">試玩體力不足</button><button data-care-demo="hunger">試玩肚子餓</button><button data-care-demo="temper">試玩脾氣爆炸</button></div><p class="small-note">只改變這次自由探索的狀態，不計分。</p></details>':''}`;}
export function foodShelf({emergency=false,ward=false,discussion=false,dining=false,items=null,notice='',diningView=null}={}){
  const supplies=items||(dining?[]:(emergency||discussion?['biscuit']:ward?['meal','biscuit','drink']:['biscuit','drink']).map(id=>({id})));
  return`<h2 id="modalTitle">${dining?diningView?.title||'餐廳沒有待領飲料。':discussion?'討論室的餅乾，拿一份吧。':emergency?'肚子空了，先吃備用餅乾。':ward?'先把這一餐吃下去。':'零食櫃，隨時補給。'}</h2><p class="modal-copy">${dining?diningView?.description||'進房時先向流動訂飲料，出房後再來領取。':discussion?'桌上備著餅乾，吃完再繼續。':emergency?'先吃點東西，手邊工作與電話會保留。':ward?notice||'護理站備著值班餐，也可以拿點餅乾和飲料。':'就在電腦旁邊，拿一份再繼續。'}</p><div class="snack-shelf">${dining&&!supplies.length?`<div class="dining-empty" role="status"><svg viewBox="0 0 160 130" aria-hidden="true"><ellipse cx="80" cy="113" rx="45" ry="7" fill="#243d4a" opacity=".1"/><path d="M52 35h56l-7 73H60Z" fill="#dbe3d5" stroke="#688b80" stroke-width="3"/><ellipse cx="80" cy="35" rx="29" ry="7" fill="#e9e4ce"/><path d="m84 13-3 73" stroke="#a9b5a2" stroke-width="6"/><path d="M59 67h43v23H59Z" fill="#6c897b"/></svg><b>目前沒有可領取的飲料</b><span>確認訂單狀態後再來看看。</span></div>`:''}${supplies.map(item=>{const id=item.id,f=SUPPLIES[id];return`<button data-eat-supply="${id}" data-food-order="${item.orderId||''}" class="supply-item"><svg viewBox="0 0 160 130" aria-hidden="true"><ellipse cx="80" cy="113" rx="53" ry="8" fill="#243d4a" opacity=".14"/>${id==='drink'?'<path d="M52 35h56l-7 73H60Z" fill="#bdc9b1" stroke="#688b80" stroke-width="3"/><ellipse cx="80" cy="35" rx="29" ry="7" fill="#e9e4ce"/><path d="m84 13-3 73" stroke="#e8dfc3" stroke-width="6"/><path d="M59 67h43v23H59Z" fill="#5c8076"/>':id==='takoyaki'?'<rect x="25" y="37" width="110" height="65" rx="10" fill="#c7b18b"/><g fill="#ba8752" stroke="#8e6749" stroke-width="3"><circle cx="52" cy="58" r="14"/><circle cx="81" cy="58" r="14"/><circle cx="110" cy="58" r="14"/><circle cx="52" cy="85" r="14"/><circle cx="81" cy="85" r="14"/><circle cx="110" cy="85" r="14"/></g><path d="m42 54 76 31m-75-1 75-31" stroke="#efe5be" stroke-width="4"/>':id==='meal'?'<rect x="26" y="30" width="108" height="74" rx="12" fill="#c7b18b" stroke="#8f7958" stroke-width="3"/><rect x="32" y="36" width="96" height="62" rx="8" fill="#e9e3ce"/><path d="M85 38v58M88 67h37" stroke="#b9a77e" stroke-width="3"/><ellipse cx="57" cy="68" rx="23" ry="24" fill="#fbf6e5"/><path d="M94 48h22v12H94Z" fill="#8ba276"/><ellipse cx="107" cy="81" rx="16" ry="10" fill="#ad7c56"/>':'<path d="m42 22 17 5 16-5 17 5 23-5-5 85-17-5-17 5-18-5-21 5Z" fill="#c7a271" stroke="#8f775b" stroke-width="3"/><rect x="47" y="40" width="59" height="45" rx="7" fill="#eee4cc"/><circle cx="77" cy="62" r="18" fill="#be9564"/><g fill="#79634e"><circle cx="72" cy="54" r="2"/><circle cx="86" cy="64" r="2"/><circle cx="72" cy="72" r="2"/></g>'}</svg><b>${item.name||f.name}</b><span>體力 +${f.energy} · 飽足 +${f.hunger}<br>脾氣 ${f.temper} · 花 ${f.minutes} 分鐘</span><strong>${item.orderId?'領取並享用':'拿一份'} →</strong></button>`;}).join('')}</div>`;
}
